package com.StudentManagementwithloginlogout.StudentManagementwithloginlogout.controlller;
import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.web.bind.annotation.*; import com.StudentManagementwithloginlogout.StudentManagementwithloginlogout.repository.ContractRepository; import com.StudentManagementwithloginlogout.StudentManagementwithloginlogout.entity.ContractStatus;
@Controller public class PageContractController { @Autowired ContractRepository repo;
 @GetMapping("/contracts") public String contracts(Model m,@RequestParam(defaultValue="") String q,@RequestParam(required=false) ContractStatus status,@RequestParam(defaultValue="0") int page){int size=8; var pg=org.springframework.data.domain.PageRequest.of(Math.max(0,page),size,org.springframework.data.domain.Sort.by("id").descending()); org.springframework.data.domain.Page<com.StudentManagementwithloginlogout.StudentManagementwithloginlogout.entity.Contract> p; if(status!=null&&!q.isBlank())p=repo.findByContractNameContainingIgnoreCaseAndStatus(q,status,pg); else if(status!=null)p=repo.findByStatus(status,pg); else if(!q.isBlank())p=repo.findByContractNameContainingIgnoreCase(q,pg); else p=repo.findAll(pg); m.addAttribute("contracts",p.getContent());m.addAttribute("currentPage",p.getNumber());m.addAttribute("totalPages",p.getTotalPages());m.addAttribute("q",q);m.addAttribute("status",status);m.addAttribute("statuses",ContractStatus.values());return "contracts"; }
 @GetMapping("/contracts/new") public String newContract(Model m){m.addAttribute("contract",new com.StudentManagementwithloginlogout.StudentManagementwithloginlogout.entity.Contract());return "contract-form";}
 @GetMapping("/contracts/{id}") public String detail(@PathVariable Long id,Model m){m.addAttribute("contract",repo.findById(id).orElseThrow());return "contract-detail";}
}
